1716: fn journal_mark(v: &Value, current_fp: &str) -> JournalMark {
1717:     if v.get("applied")
1718:         .is_some_and(|a| !a.is_null() && *a != Value::Bool(false))
1719:     {
1720:         return JournalMark::Applied;
1721:     }
1722:     match v.get("applying") {
1723:         None | Some(Value::Null) => JournalMark::Plain,
1724:         Some(Value::String(f)) if f == current_fp => JournalMark::Unwritten,
1725:         Some(_) => JournalMark::Applying,
1726:     }
