1937: fn acquire_machine_lock(lock_path: &Path, budget: LockBudget) -> Option<std::fs::File> {
1938:     let open = || -> std::io::Result<std::fs::File> {
1939:         let f = OpenOptions::new()
1940:             .read(true)
1941:             .write(true)
1942:             .create(true)
1943:             .truncate(false)
1944:             .open(lock_path)?;
1945:         match f.try_lock() {
1946:             Ok(()) => Ok(f),
1947:             Err(std::fs::TryLockError::WouldBlock) => {
1948:                 Err(std::io::Error::from(std::io::ErrorKind::WouldBlock))
1949:             }
1950:             Err(std::fs::TryLockError::Error(e)) => Err(e),
1951:         }
1952:     };
1953:     let attempt = std::time::Duration::from_secs_f64(budget.attempt_secs);
1954:     for _ in 0..budget.attempts {
1955:         let started = std::time::Instant::now();
1956:         let mut delay = std::time::Duration::from_millis(25);
1957:         loop {
1958:             match open() {
1959:                 Ok(f) => return Some(f),
1960:                 Err(_) => {
1961:                     if started.elapsed() >= attempt {
1962:                         break;
1963:                     }
1964:                     std::thread::sleep(delay);
1965:                     delay = (delay * 2).min(std::time::Duration::from_millis(500));
1966:                 }
1967:             }
1968:         }
1969:     }
1970:     None
1971: }
